function refreshOrder(){const visited=new Set(),active=new Set(),ids=[],map=new Map(LESSONS.map(l=>[l.id,l]));function visit(id){if(visited.has(id))return;if(active.has(id)||!map.has(id))throw Error('Invalid curriculum prerequisite '+id);active.add(id);for(const p of map.get(id).prereq||[])visit(p);active.delete(id);visited.add(id);ids.push(id);}for(const week of CURRICULUM8.schedule)for(const id of week.lessonIds)visit(id);for(const l of LESSONS)visit(l.id);CURRICULUM8.lessonOrder=ids;CURRICULUM8.totalLessons=LESSONS.length;CURRICULUM8.scope=[LESSONS.length+'节课程；96周电子优先路线，电脑基础保留为按需补课。',LESSONS.length+' lessons; a 96-week electronics-first route with optional computer fundamentals.'];}
