function all(){return [...data,...extra];}
const positive=n=>{if(!Number.isFinite(n)||n<=0)throw Error('A finite positive value is required');return n;};
function divider(v,r1,r2,rl=Infinity){positive(v);positive(r1);positive(r2);if(rl!==Infinity)positive(rl);const lower=rl===Infinity?r2:1/(1/r2+1/rl),out=v*lower/(r1+lower),unloaded=v*r2/(r1+r2);return {out,unloaded,upperCurrent:(v-out)/r1,lowerCurrent:out/r2,loadCurrent:rl===Infinity?0:out/rl,errorPercent:100*(unloaded-out)/unloaded};}
function led(v,vf,r){positive(v);if(!Number.isFinite(vf)||vf<0)throw Error('Invalid forward voltage');positive(r);const current=Math.max(0,v-vf)/r;return{current,power:current*current*r,headroom:Math.max(0,v-vf)};}
function rc(v,r,c,t){positive(v);positive(r);positive(c);if(!Number.isFinite(t)||t<0)throw Error('Invalid time');const tau=r*c;return{tau,fc:1/(2*Math.PI*tau),out:v*(1-Math.exp(-t/tau)),current:v/r*Math.exp(-t/tau)};}
function quizHTML(d){return `<section class="e11-quiz" data-e11-quiz="${d.id}"><h2>${T('换条件，再判断','Change conditions and decide again')}</h2>${d.quiz.map((x,i)=>{const id='electronics-'+(i+1),draft=ZTHProgress9.getDraft(d.id,id)?.value;return `<form data-e11-q="${i}"><fieldset><legend>${E(T(...x.question))}</legend>${x.options.map((o,n)=>`<label><input type="radio" name="e11-answer" value="${n}" ${draft===String(n)?'checked':''}>${E(T(...o))}</label>`).join('')}</fieldset><button>${T('提交判断','Check answer')}</button><p role="status" data-e11-feedback></p><small data-e11-attempts>${T('提交记录：','Attempts: ')}${ZTHProgress9.getAttempts(d.id,id).length}</small></form>`;}).join('')}</section>`;}
let timer=null,elapsed=0,playing=false,benchMode='divider';
function stop(){if(timer)clearInterval(timer);timer=null;playing=false;}
function benchHTML(mode){return `<section class="e11-bench" data-e11-bench="${mode}"><span class="eyebrow7">${T('电路推演台 · 理想低压模型','CIRCUIT STUDY · IDEAL LOW-VOLTAGE MODEL')}</span><h2>${T(...({divider:['接上负载，电压会怎样？','What changes when a load is connected?'],led:['让电流与功率同时可见','See current and power together'],rc:['看见充电的时间尺度','See the timescale of charging']}[mode]))}</h2><div class="e11-controls"><label>${T('电源 / V','Supply / V')}<input data-e11-input="v" type="number" min="0.1" max="24" step="0.1" value="5"></label>${mode==='divider'?`<label>R1 / kΩ<input data-e11-input="r1" type="number" min="0.1" max="10000" step="0.1" value="10"></label><label>R2 / kΩ<input data-e11-input="r2" type="number" min="0.1" max="10000" step="0.1" value="10"></label><label>${T('负载 / kΩ','Load / kΩ')}<select data-e11-input="rl"><option value="Infinity">${T('开路','Open')}</option><option value="100">100</option><option value="10" selected>10</option><option value="1">1</option></select></label>`:mode==='led'?`<label>VF / V<input data-e11-input="vf" type="number" min="0" max="12" step="0.1" value="2"></label><label>R / Ω<input data-e11-input="r" type="number" min="1" max="1000000" step="1" value="330"></label>`:`<label>R / kΩ<input data-e11-input="r" type="number" min="0.1" max="1000" step="0.1" value="10"></label><label>C / µF<select data-e11-input="c"><option value="1" selected>1</option><option value="10">10</option><option value="100">100</option></select></label>`}</div><div data-e11-visual></div><div class="e11-readouts" aria-live="polite" data-e11-readouts></div><p data-e11-status role="status"></p>${mode==='rc'?`<div class="e11-actions"><button data-e11-action="play">${T('开始 / 继续','Start / resume')}</button><button data-e11-action="pause">${T('暂停','Pause')}</button><button data-e11-action="reset">${T('回到初始状态','Reset to initial state')}</button></div><p>${T('动画将5τ缩放为5秒观看，读数显示真实模型时间。','Playback maps five τ to five viewing seconds; readings show modeled circuit time.')}</p>`:''}<p class="e11-scope">${T('方程推演用于解释原理；不模拟容差、温升、寄生或真实器件失效。','Equations illustrate principles; tolerance, heating, parasitics and device failures are not simulated.')}</p></section>`;}
function draw(){const host=document.querySelector('[data-e11-bench]');if(!host)return;const mode=host.dataset.e11Bench,get=k=>Number(host.querySelector(`[data-e11-input="${k}"]`).value),v=get('v'),fmt=(x,n=3)=>Number(x).toFixed(n);try{if(v>24)throw Error('Supply range is 0.1–24 V');const out=host.querySelector('[data-e11-readouts]'),visual=host.querySelector('[data-e11-visual]');let cells=[],svg='';if(mode==='divider'){const z=divider(v,get('r1')*1000,get('r2')*1000,get('rl')*1000);cells=[[T('空载','Unloaded'),fmt(z.unloaded)+' V'],[T('带载','Loaded'),fmt(z.out)+' V'],[T('下降','Droop'),fmt(z.errorPercent,2)+'%'],['I1 / I2 / IL',[z.upperCurrent,z.lowerCurrent,z.loadCurrent].map(x=>fmt(x*1000)).join(' / ')+' mA']];svg=`<path d="M80 45H190V85M190 135V180H330V215M190 180V215M190 265V300H80V45M330 265V300H190"/><rect x="172" y="85" width="36" height="50"/><rect x="172" y="215" width="36" height="50"/><rect x="312" y="215" width="36" height="50"/><circle cx="190" cy="180" r="6"/><text x="214" y="115">R1</text><text x="214" y="245">R2</text><text x="355" y="245">RL</text><text x="23" y="164">${fmt(v,1)} V</text><text x="218" y="168">${fmt(z.out)} V</text><path class="e11-current" d="M80 45H190V180H330V300H80Z"/>`;}else if(mode==='led'){const z=led(v,get('vf'),get('r'));cells=[[T('电流','Current'),fmt(z.current*1000)+' mA'],[T('电阻功耗','Resistor power'),fmt(z.power*1000)+' mW'],[T('电阻压降','Resistor drop'),fmt(z.headroom)+' V']];svg=`<path d="M80 70H190V105M190 155V190M190 240V290H80V70"/><rect x="172" y="105" width="36" height="50"/><path d="M170 190L190 225L210 190ZM170 227H210"/><circle class="e11-led" cx="190" cy="210" r="42" style="opacity:${Math.min(.8,z.current*60)}"/><text x="225" y="140">R ${get('r')} Ω</text><text x="230" y="220">LED ${get('vf')} V</text><text x="20" y="170">${v} V</text>`;host.querySelector('[data-e11-status]').textContent=z.current>.02?T('超过20 mA示例阈值，请核对真实LED与驱动器额定。','Above the illustrative 20 mA threshold; verify actual LED and driver ratings.'):z.current===0?T('供电低于设定VF，固定压降模型不导通。','Supply is below set VF; the fixed-drop model does not conduct.'):'';}else{const tau=get('r')*1000*get('c')/1e6,z=rc(v,get('r')*1000,get('c')/1e6,elapsed*tau);cells=[['τ',fmt(tau*1000)+' ms'],['fc',fmt(z.fc)+' Hz'],['t',fmt(elapsed*tau*1000)+' ms'],['VC',fmt(z.out)+' V']];const pts=Array.from({length:101},(_,i)=>`${50+i*3.5},${280-220*(1-Math.exp(-i/20))}`).join(' ');svg=`<path d="M50 45V280H410"/><polyline class="e11-curve" points="${pts}"/><path class="e11-cursor" d="M${50+elapsed*70} 50V280"/><circle cx="${50+elapsed*70}" cy="${280-220*z.out/v}" r="7"/><text x="20" y="45">VC</text><text x="390" y="310">5τ</text><text x="60" y="310">0</text>`;host.querySelector('[data-e11-status]').textContent=elapsed>=5?T('到达5τ，已暂停。可复位重做。','Reached five τ and paused. Reset to repeat.'):playing?T('正在播放','Playing'):T('已暂停 / 初始状态','Paused / initial state');}visual.innerHTML=`<svg viewBox="0 0 460 330" role="img" aria-label="${T('电路与状态图','Circuit and state diagram')}">${svg}</svg>`;out.innerHTML=cells.map(([k,x])=>`<div><span>${E(k)}</span><strong>${E(x)}</strong></div>`).join('');}catch(e){stop();host.querySelector('[data-e11-status]').textContent=T('请输入有限的正数并保持单位一致。','Enter finite positive values with consistent units.');}}
