const oldLesson=lesson4;lesson4=function(){let html=oldLesson();const d=all().find(x=>x.id===UI4.id);if(!d)return html;html=html.replace(/<button data-lab="[^"]+">[^<]*<\/button>/,`<button data-e11-scroll>${T('跳到本课任务','Jump to this lesson task')} ↓</button>`);html=html.replace('<section class="case8"',quizHTML(d)+'<section class="case8"');const side=d.bench?benchHTML(d.bench):`<section class="e11-lab-link"><span class="eyebrow7">${T('从读懂到会验证','FROM READING TO VERIFICATION')}</span><h2>${T('带着这份任务去操作','Take this task to the workbench')}</h2><p>${E(T(...d.task))}</p><button data-lesson="${d.pre[0]}">${T('复习先修原理','Review the prerequisite')} ↗</button><p>${T('记录预测、测点、实际读数与偏差；此处不以无关模型代替本课电路。','Record prediction, probe point, reading and discrepancy. The related bench illustrates selected concepts, not this entire circuit.')}</p></section>`;return html.replace(/<aside class="lesson-work4 lesson-work7"[\s\S]*?<\/aside>/,`<aside class="lesson-work4 lesson-work7 e11-work">${side}</aside>`);};
