document.addEventListener('input',e=>{if(e.target.matches('[data-e11-input]')){stop();elapsed=0;draw();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-e11-input]')){stop();elapsed=0;draw();}const f=e.target.closest('[data-e11-q]');if(f&&e.target.name==='e11-answer')ZTHProgress9.setDraft(f.closest('[data-e11-quiz]').dataset.e11Quiz,'electronics-'+(+f.dataset.e11Q+1),e.target.value);});
document.addEventListener('click',e=>{if(e.target.closest('[data-e11-scroll]'))document.querySelector('.e11-work')?.scrollIntoView({block:'start'});const a=e.target.closest('[data-e11-action]')?.dataset.e11Action;if(!a)return;if(a==='pause')stop();if(a==='reset'){stop();elapsed=0;}if(a==='play'&&!playing){if(elapsed>=5)elapsed=0;playing=true;timer=setInterval(()=>{elapsed=Math.min(5,elapsed+.05);if(elapsed>=5)stop();draw();},50);}draw();});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-e11-q]');if(!form)return;e.preventDefault();const id=form.closest('[data-e11-quiz]').dataset.e11Quiz,d=all().find(x=>x.id===id),index=+form.dataset.e11Q,question=d.quiz[index],selected=form.querySelector('input:checked'),out=form.querySelector('[data-e11-feedback]');if(!selected){out.textContent=T('先选一个判断。','Select an answer first.');return;}const n=+selected.value,correct=n===question.correct,qid='electronics-'+(index+1);ZTHProgress9.recordAttempt({lessonId:id,questionId:qid,kind:'choice',answer:T(...question.options[n]),options:question.options.map(p=>T(...p)),correct,feedback:T(...question.explanation)});ZTHProgress9.setDraft(id,qid,String(n));out.textContent=(correct?T('正确。','Correct.'):T('再想一想。','Review this.'))+' '+T(...question.explanation);form.querySelector('[data-e11-attempts]').textContent=T('提交记录：','Attempts: ')+ZTHProgress9.getAttempts(id,qid).length;});
return{data,refs,registerExtra,includeExtra,divider,led,rc,draw,stop,get elapsed(){return elapsed;},get playing(){return playing;},optionalIds:[...optionalIds]};
